/** Only the separately admitted local runner may apply the fingerprinted candidate. */
@EnabledIfEnvironmentVariable(named="CINENEST_CUSTOMER_RUN",matches="/tmp/cinenest-customer-credential-[^/]+")
public class CustomerCredentialPostgresTest {
    public static void sqlAdmission()throws Exception{
        Path run=Path.of(System.getenv("CINENEST_CUSTOMER_RUN"));
        if(!Files.isDirectory(run)||Files.isSymbolicLink(run)||!run.toRealPath().equals(run.toAbsolutePath().normalize())||!Files.getPosixFilePermissions(run).equals(java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"))||!System.getenv("CINENEST_DB_URL").startsWith("jdbc:postgresql://127.0.0.1:"))throw new IllegalStateException("Owned local qualification required");
        var ownership=com.nimbusds.jose.util.JSONObjectUtils.parse(Files.readString(run.resolve("ownership.json")));var database=com.nimbusds.jose.util.JSONObjectUtils.parse(Files.readString(run.resolve("database-ownership.json")));if(!"SYNTHETIC_TEST_ONLY".equals(ownership.get("classification"))||!run.getFileName().toString().equals(ownership.get("name"))||!ownership.get("name").equals(database.get("name"))||!String.valueOf(database.get("containerId")).matches("[0-9a-f]{64}")||!System.getenv("CINENEST_DB_URL").equals(database.get("jdbcUrl")))throw new IllegalStateException("Owned database binding required");
        String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(Path.of("src/main/resources/db/migration/V46__customer_credential_lifecycle.sql"))));
        if(!hash.equals(System.getenv("CINENEST_CUSTOMER_SQL_SHA256")))throw new IllegalStateException("Exact SQL admission required");
    }
    public static final class Fixture implements AutoCloseable {
        public final String name="cn_customer_"+UUID.randomUUID().toString().replace("-","");
        public final String admin,url,adminUser=System.getenv("CINENEST_DB_USER"),adminPassword=System.getenv("CINENEST_DB_PASSWORD");
        public final String user="cn_rt_"+UUID.randomUUID().toString().replace("-",""),migrator="cn_mig_"+UUID.randomUUID().toString().replace("-",""),password=UUID.randomUUID().toString(),migrationPassword=UUID.randomUUID().toString();
        public final JdbcClient jdbc;public final JdbcClient owner;final JdbcCustomerCredentialRepository repository;
        final CustomerCredentialConfiguration.Crypto crypto=new CustomerCredentialConfiguration.Crypto(CustomerCredentialServiceTest.keys());
        final Map<String,CustomerCredentialConfiguration.DeliveryMessage> mail=new ConcurrentHashMap<>();
        final CustomerCredentialService service;final CustomerCredentialDeliveryDispatcher dispatcher;
        public Fixture()throws Exception{this(false,CustomerCredentialServiceTest.settings());}
        public Fixture(boolean upgrade,CustomerCredentialConfiguration.Settings settings)throws Exception{
            sqlAdmission();admin=System.getenv("CINENEST_DB_URL");int slash=admin.indexOf('/',"jdbc:postgresql://".length()),query=admin.indexOf('?',slash);url=admin.substring(0,slash+1)+name+(query<0?"":admin.substring(query));
            try(var c=DriverManager.getConnection(admin,adminUser,adminPassword);var s=c.createStatement()){s.execute("CREATE ROLE "+migrator+" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD '"+migrationPassword+"'");s.execute("CREATE ROLE "+user+" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD '"+password+"'");s.execute("CREATE DATABASE "+name+" OWNER "+migrator);}
            var migrationDs=new DriverManagerDataSource(url,migrator,migrationPassword);owner=JdbcClient.create(migrationDs);if(upgrade){Flyway.configure().dataSource(migrationDs).locations("classpath:db/migration").target("45").load().migrate();owner.sql("INSERT INTO cinenest_identity.account(account_id,synthetic,eligibility,revision) VALUES(:id,true,'INELIGIBLE',0)").param("id",UUID.randomUUID()).update();}Flyway.configure().dataSource(migrationDs).locations("classpath:db/migration").load().migrate();
            owner.sql("REVOKE CONNECT,TEMP ON DATABASE "+name+" FROM PUBLIC").update();owner.sql("REVOKE CREATE ON SCHEMA public FROM PUBLIC").update();owner.sql("GRANT CONNECT ON DATABASE "+name+" TO "+user).update();owner.sql("GRANT USAGE ON SCHEMA cinenest_identity,public TO "+user).update();owner.sql("GRANT SELECT ON public.flyway_schema_history TO "+user).update();owner.sql("GRANT SELECT,INSERT,UPDATE ON cinenest_identity.account,cinenest_identity.customer_credential,cinenest_identity.customer_capability,cinenest_identity.customer_outbox,cinenest_identity.customer_abuse TO "+user).update();owner.sql("GRANT SELECT,INSERT ON cinenest_identity.security_audit,cinenest_identity.customer_key_binding,cinenest_identity.customer_registration_retirement,cinenest_identity.customer_command,cinenest_identity.customer_audit TO "+user).update();owner.sql("GRANT SELECT,INSERT,UPDATE,DELETE ON cinenest_identity.http_session,cinenest_identity.http_session_attributes,cinenest_identity.customer_lease TO "+user).update();
            var ds=new DriverManagerDataSource(url,user,password);jdbc=JdbcClient.create(ds);repository=new JdbcCustomerCredentialRepository(jdbc,new DataSourceTransactionManager(ds));
            var gateway=new CustomerCredentialConfiguration.DeliveryGateway(){public boolean qualified(){return true;}public boolean qualificationOnly(){return true;}public CustomerCredentialConfiguration.DeliveryStatus send(CustomerCredentialConfiguration.DeliveryMessage m){mail.put(m.address()+":"+m.purpose(),m);return CustomerCredentialConfiguration.DeliveryStatus.ACCEPTED;}};
            dispatcher=new CustomerCredentialDeliveryDispatcher(repository,crypto,gateway,CustomerCredentialServiceTest.settings());service=new CustomerCredentialService(repository,crypto,settings,dispatcher);
        }
        public CustomerCredentialConfiguration.Keys keys(){return crypto.keys;}
        public String lookup(String address){return crypto.mac("ADDRESS",address);}
        public void dispatchPending(){dispatcher.dispatchPending(4);}
        public Map<String,CustomerCredentialConfiguration.DeliveryMessage> mailbox(){return mail;}
        UUID register(String address){assertThat(service.register(UUID.randomUUID(),address,CustomerCredentialServiceTest.PASSWORD,"TEST_PRIVACY_V1","loopback").status()).isEqualTo(202);return jdbc.sql("SELECT account_id FROM cinenest_identity.customer_credential WHERE address_lookup=:lookup AND abandoned_at IS NULL").param("lookup",crypto.mac("ADDRESS",address)).query(UUID.class).single();}
        String token(String address,String purpose){dispatcher.dispatchPending(4);return mail.get(address+":"+purpose).token();}
        void verify(String address){assertThat(service.verify(UUID.randomUUID(),token(address,"VERIFY_EMAIL"),CustomerCredentialServiceTest.PASSWORD,"loopback").status()).isEqualTo(204);}
        int count(String table){if(!Set.of("customer_credential","customer_command","customer_capability","customer_outbox","customer_audit","customer_abuse").contains(table))throw new IllegalArgumentException();return jdbc.sql("SELECT count(*) FROM cinenest_identity."+table).query(Integer.class).single();}
        @Override public void close()throws Exception{try(var c=DriverManager.getConnection(admin,adminUser,adminPassword);var p=c.prepareStatement("SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname=? AND pid<>pg_backend_pid()")){p.setString(1,name);p.execute();try(var s=c.createStatement()){s.execute("DROP DATABASE "+name);s.execute("DROP ROLE "+user);s.execute("DROP ROLE "+migrator);}}}
    }
    @Test void cleanMigrationAndFullCredentialLifecycle()throws Exception{try(var f=new Fixture()){UUID account=f.register("customer@qualification.invalid");assertThat(f.service.login(UUID.randomUUID(),"customer@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"loopback").status()).isEqualTo(401);f.verify("customer@qualification.invalid");assertThat(f.service.login(UUID.randomUUID(),"customer@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"loopback").account()).isEqualTo(account);f.service.requestRecovery(UUID.randomUUID(),"customer@qualification.invalid","loopback");assertThat(f.service.recover(UUID.randomUUID(),f.token("customer@qualification.invalid","RECOVER_ACCOUNT"),"Different qualification password 2026!","loopback").status()).isEqualTo(204);assertThat(f.repository.account(account,false).orElseThrow().epoch()).isEqualTo(1);assertThat(f.count("customer_audit")).isEqualTo(f.count("customer_command"));}}
    @Test void concurrentSameAddressCreatesOnlyOneIdentityAndDelivery()throws Exception{var policy=new CustomerCredentialConfiguration.Settings("TEST_POLICY_V1","TEST_PRIVACY_V1","TEST_DELIVERY_V1","ASCII_CASEFOLD_V1",900,100,60,2,3600,60,true);try(var f=new Fixture(false,policy);var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var task=(Callable<Integer>)()->{start.await();return f.service.register(UUID.randomUUID(),"race@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"TEST_PRIVACY_V1","loopback").status();};var a=pool.submit(task);var b=pool.submit(task);start.countDown();assertThat(a.get()).isEqualTo(202);assertThat(b.get()).isEqualTo(202);assertThat(f.count("customer_credential")).isEqualTo(1);assertThat(f.count("customer_outbox")).isEqualTo(1);}}
    @Test void exactRetryAndChangedPayloadAreDistinct()throws Exception{try(var f=new Fixture()){UUID command=UUID.randomUUID();assertThat(f.service.register(command,"retry@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"TEST_PRIVACY_V1","loopback").status()).isEqualTo(202);assertThat(f.service.register(command,"retry@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"TEST_PRIVACY_V1","loopback").status()).isEqualTo(202);assertThatThrownBy(()->f.service.register(command,"retry@qualification.invalid","Changed qualification password 2026!","TEST_PRIVACY_V1","loopback")).isInstanceOf(CustomerCredentialService.Refused.class);assertThat(f.count("customer_command")).isEqualTo(1);}}
    @Test void capabilityIsSingleUseUnderConcurrency()throws Exception{try(var f=new Fixture();var pool=Executors.newFixedThreadPool(2)){f.register("cap@qualification.invalid");String token=f.token("cap@qualification.invalid","VERIFY_EMAIL");var task=(Callable<Integer>)()->{try{return f.service.verify(UUID.randomUUID(),token,CustomerCredentialServiceTest.PASSWORD,"loopback").status();}catch(CustomerCredentialService.Refused e){return e.status;}};var a=pool.submit(task);var b=pool.submit(task);assertThat(List.of(a.get(),b.get())).containsExactlyInAnyOrder(204,409);}}
    @Test void wrongPurposeExpiredAndSuspendedCapabilitiesDeny()throws Exception{try(var f=new Fixture()){UUID id=f.register("deny@qualification.invalid");String token=f.token("deny@qualification.invalid","VERIFY_EMAIL");assertThatThrownBy(()->f.service.recover(UUID.randomUUID(),token,"Different qualification password 2026!","loopback")).isInstanceOf(CustomerCredentialService.Refused.class);f.jdbc.sql("UPDATE cinenest_identity.account SET eligibility='SUSPENDED',revision=revision+1 WHERE account_id=:id").param("id",id).update();assertThatThrownBy(()->f.service.verify(UUID.randomUUID(),token,CustomerCredentialServiceTest.PASSWORD,"loopback")).isInstanceOf(CustomerCredentialService.Refused.class);}}
    @Test void immutableHistoryAndPopulatedCascadeTruncateAreProtected()throws Exception{try(var f=new Fixture()){f.register("history@qualification.invalid");for(String sql:List.of("DELETE FROM cinenest_identity.customer_audit","UPDATE cinenest_identity.customer_command SET status=204","TRUNCATE cinenest_identity.account CASCADE"))assertThatThrownBy(()->f.owner.sql(sql).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.count("customer_credential")).isEqualTo(1);}}
    @Test void emptyCleanupAllowedOnlyWithReadCommitted()throws Exception{try(var f=new Fixture()){f.owner.sql("TRUNCATE cinenest_identity.account CASCADE").update();try(var c=DriverManager.getConnection(f.url,f.migrator,f.migrationPassword)){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);try(var st=c.createStatement()){assertThatThrownBy(()->st.execute("TRUNCATE cinenest_identity.customer_credential CASCADE")).isInstanceOfSatisfying(SQLException.class,e->assertThat(e.getSQLState()).isEqualTo("23514"));}finally{c.rollback();}}}}
    @Test void publicCannotReadPrivateCredentialHistory()throws Exception{try(var f=new Fixture()){assertThat(f.jdbc.sql("SELECT count(*) FROM pg_database d CROSS JOIN LATERAL aclexplode(d.datacl) acl WHERE d.datname=current_database() AND acl.grantee=0 AND acl.privilege_type IN('CONNECT','TEMPORARY')").query(Integer.class).single()).isZero();assertThat(f.jdbc.sql("SELECT count(*) FROM information_schema.table_privileges WHERE table_schema='cinenest_identity' AND table_name LIKE 'customer_%' AND grantee='PUBLIC'").query(Integer.class).single()).isZero();}}
    @Test void protectedOutboxContainsNoAddressOrTokenPlaintext()throws Exception{try(var f=new Fixture()){f.register("sealed@qualification.invalid");byte[] payload=f.jdbc.sql("SELECT sealed_payload FROM cinenest_identity.customer_outbox").query(byte[].class).single();String wire=new String(payload,java.nio.charset.StandardCharsets.ISO_8859_1);assertThat(wire).doesNotContain("sealed@qualification.invalid",f.token("sealed@qualification.invalid","VERIFY_EMAIL"));}}
    @Test void failedTransactionRollsBackCredentialAndOutboxButNotAbuse()throws Exception{try(var f=new Fixture()){f.owner.sql("CREATE FUNCTION cinenest_identity.inject_customer_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Injected test failure'; END $$").update();f.owner.sql("CREATE TRIGGER inject_customer_failure BEFORE INSERT ON cinenest_identity.customer_audit FOR EACH ROW EXECUTE FUNCTION cinenest_identity.inject_customer_failure()").update();assertThatThrownBy(()->f.register("rollback@qualification.invalid")).isInstanceOf(RuntimeException.class);assertThat(f.count("customer_credential")).isZero();assertThat(f.count("customer_outbox")).isZero();assertThat(f.count("customer_abuse")).isGreaterThan(0);}}    @Test void pendingDeliverySurvivesCommitBeforeWorkerAndSkipsRevokedMessages()throws Exception{try(var f=new Fixture()){f.register("worker@qualification.invalid");assertThat(f.mail).isEmpty();f.dispatchPending();assertThat(f.mail).hasSize(1);f.verify("worker@qualification.invalid");for(int i=0;i<5;i++)f.service.requestRecovery(UUID.randomUUID(),"worker@qualification.invalid","loopback");f.dispatchPending();assertThat(f.mail).hasSize(2);assertThat(f.jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_outbox WHERE purpose='RECOVER' AND state='ACCEPTED'").query(Integer.class).single()).isEqualTo(1);}}
    @Test void unapprovedKeyRotationCannotCreateDuplicateAddress()throws Exception{try(var f=new Fixture()){f.register("keys@qualification.invalid");var changed=new CustomerCredentialConfiguration.Crypto(CustomerCredentialServiceTest.keys());assertThatThrownBy(()->new CustomerCredentialService(f.repository,changed,CustomerCredentialServiceTest.settings(),f.dispatcher)).isInstanceOf(CustomerCredentialService.Refused.class);assertThat(f.count("customer_credential")).isEqualTo(1);}}
    @Test void restrictedRuntimeCannotCreateRolesDatabasesTablesOrReadOtherModules()throws Exception{try(var f=new Fixture()){assertThat(f.jdbc.sql("SELECT rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls FROM pg_roles WHERE rolname=current_user").query(Boolean.class).single()).isFalse();for(String sql:List.of("CREATE ROLE cn_forbidden_test_role","CREATE DATABASE cn_forbidden_test_database","CREATE TABLE cinenest_identity.forbidden_table(id integer)","CREATE TEMP TABLE forbidden_temp(id integer)","SELECT * FROM cinenest_payments.bank_request"))assertThatThrownBy(()->f.jdbc.sql(sql).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);}}
    @Test void populatedV45UpgradePreservesHistoricalAccountAndMigration()throws Exception{try(var f=new Fixture(true,CustomerCredentialServiceTest.settings())){assertThat(f.owner.sql("SELECT count(*) FROM cinenest_identity.account WHERE synthetic").query(Integer.class).single()).isEqualTo(1);assertThat(f.owner.sql("SELECT count(*) FROM public.flyway_schema_history WHERE success").query(Integer.class).single()).isEqualTo(45);assertThat(f.owner.sql("SELECT script FROM public.flyway_schema_history WHERE version='45'").query(String.class).single()).isEqualTo("V45__synthetic_staff_session_events.sql");}}
    @Test void verificationRequiresChosenPasswordAndDoesNotConsumeOnWrongProof()throws Exception{try(var f=new Fixture()){f.register("proof@qualification.invalid");String token=f.token("proof@qualification.invalid","VERIFY_EMAIL");assertThatThrownBy(()->f.service.verify(UUID.randomUUID(),token,"Wrong chosen password 2026!","loopback")).isInstanceOfSatisfying(CustomerCredentialService.Refused.class,e->assertThat(e.status).isEqualTo(401));assertThat(f.service.verify(UUID.randomUUID(),token,CustomerCredentialServiceTest.PASSWORD,"loopback").status()).isEqualTo(204);}}
    @Test void lostVerificationCanReissueWithKnownPasswordAndOldTokenIsRevoked()throws Exception{try(var f=new Fixture()){f.register("resend@qualification.invalid");String old=f.token("resend@qualification.invalid","VERIFY_EMAIL");Thread.sleep(1100);f.service.register(UUID.randomUUID(),"resend@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"TEST_PRIVACY_V1","loopback");f.dispatchPending();String fresh=f.token("resend@qualification.invalid","VERIFY_EMAIL");assertThat(fresh).isNotEqualTo(old);assertThatThrownBy(()->f.service.verify(UUID.randomUUID(),old,CustomerCredentialServiceTest.PASSWORD,"loopback")).isInstanceOf(CustomerCredentialService.Refused.class);assertThat(f.service.verify(UUID.randomUUID(),fresh,CustomerCredentialServiceTest.PASSWORD,"loopback").status()).isEqualTo(204);}}
    @Test void expiredUnverifiedReservationPreservesHistoryAndAllowsFreshRegistration()throws Exception{var shortPolicy=new CustomerCredentialConfiguration.Settings("TEST_POLICY_V1","TEST_PRIVACY_V1","TEST_DELIVERY_V1","ASCII_CASEFOLD_V1",1,100,60,2,3,1,true);try(var f=new Fixture(false,shortPolicy)){UUID abandoned=f.register("expired@qualification.invalid");Thread.sleep(3100);UUID next=f.register("expired@qualification.invalid");assertThat(next).isNotEqualTo(abandoned);assertThat(f.count("customer_credential")).isEqualTo(2);assertThat(f.jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_credential WHERE abandoned_at IS NOT NULL").query(Integer.class).single()).isEqualTo(1);}}
    @Test void changedCurrentPolicyCannotSendRetainedPendingDelivery()throws Exception{try(var f=new Fixture()){f.register("policy@qualification.invalid");var current=new CustomerCredentialConfiguration.Settings("TEST_POLICY_V2","TEST_PRIVACY_V2","TEST_DELIVERY_V2","ASCII_CASEFOLD_V1",900,100,60,2,3600,1,true);var calls=new java.util.concurrent.atomic.AtomicInteger();var gateway=new CustomerCredentialConfiguration.DeliveryGateway(){public boolean qualified(){return true;}public boolean qualificationOnly(){return true;}public CustomerCredentialConfiguration.DeliveryStatus send(CustomerCredentialConfiguration.DeliveryMessage message){calls.incrementAndGet();return CustomerCredentialConfiguration.DeliveryStatus.ACCEPTED;}};new CustomerCredentialDeliveryDispatcher(f.repository,f.crypto,gateway,current).dispatchPending(4);assertThat(calls.get()).isZero();assertThat(f.jdbc.sql("SELECT state FROM cinenest_identity.customer_outbox").query(String.class).single()).isEqualTo("PENDING");}}

    @Test void retainedPolicyPrivacyAndDeliveryDoNotEnumerateKnownAddresses()throws Exception{
        try(var f=new Fixture()){
            f.register("stale@qualification.invalid");f.verify("stale@qualification.invalid");int before=f.count("customer_outbox");
            for(int changed=0;changed<3;changed++){
                var current=new CustomerCredentialConfiguration.Settings(changed==0?"TEST_POLICY_V2":"TEST_POLICY_V1",changed==1?"TEST_PRIVACY_V2":"TEST_PRIVACY_V1",changed==2?"TEST_DELIVERY_V2":"TEST_DELIVERY_V1","ASCII_CASEFOLD_V1",900,100,60,2,3600,1,true);
                var service=new CustomerCredentialService(f.repository,f.crypto,current,f.dispatcher);
                assertThat(service.login(UUID.randomUUID(),"stale@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"loopback").status()).isEqualTo(401);
                assertThat(service.login(UUID.randomUUID(),"unknown@qualification.invalid",CustomerCredentialServiceTest.PASSWORD,"loopback").status()).isEqualTo(401);
                assertThat(service.requestRecovery(UUID.randomUUID(),"stale@qualification.invalid","loopback").status()).isEqualTo(202);
                assertThat(service.requestRecovery(UUID.randomUUID(),"unknown@qualification.invalid","loopback").status()).isEqualTo(202);
            }
            assertThat(f.count("customer_outbox")).isEqualTo(before);
        }
    }

    @Test void schemaInspectorRejectsUnapprovedFutureHistoryOnActualPostgres()throws Exception{
        try(var f=new Fixture()){
            var ds=new DriverManagerDataSource(f.url,f.user,f.password);
            CustomerCredentialConfiguration.validateExistingSchema(CustomerCredentialConfiguration.schemaInspector(ds));
            f.owner.sql("INSERT INTO public.flyway_schema_history(installed_rank,version,description,type,script,checksum,installed_by,execution_time,success) SELECT max(installed_rank)+1,'47','unapproved future test fixture','SQL','V47__unapproved_fixture.sql',0,current_user,0,true FROM public.flyway_schema_history").update();
            assertThatThrownBy(()->CustomerCredentialConfiguration.validateExistingSchema(CustomerCredentialConfiguration.schemaInspector(ds))).isInstanceOf(org.flywaydb.core.api.FlywayException.class);
        }
    }

}
